/* Chart rendering for the SeaNergy dossier.
 *
 * No library, no network. Every series comes from window.SEANERGY in data.js,
 * which is generated by scripts/site-data.mjs out of the app's own physics core.
 * If the physics changes, regenerate data.js and the charts follow.
 */
(function () {
  'use strict';

  var D = window.SEANERGY;
  var NS = 'http://www.w3.org/2000/svg';

  function el(name, attrs, text) {
    var n = document.createElementNS(NS, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    if (text !== undefined) n.textContent = text;
    return n;
  }

  function nice(v) {
    if (v >= 1000) return Math.round(v / 100) * 100;
    if (v >= 100) return Math.round(v / 10) * 10;
    return Math.round(v * 10) / 10;
  }

  /**
   * Line plot. `series` is [{points:[[x,y]...], colour, dash, label}].
   * Axes are linear unless log:'y'.
   */
  function plot(target, opts) {
    var host = document.getElementById(target);
    if (!host) return;

    var W = 720, H = opts.height || 250;
    var m = { l: 58, r: 14, t: 14, b: 40 };
    var pw = W - m.l - m.r, ph = H - m.t - m.b;

    var xs = [], ys = [];
    opts.series.forEach(function (s) {
      s.points.forEach(function (p) { xs.push(p[0]); ys.push(p[1]); });
    });
    var x0 = opts.xMin !== undefined ? opts.xMin : Math.min.apply(null, xs);
    var x1 = opts.xMax !== undefined ? opts.xMax : Math.max.apply(null, xs);
    var y0 = opts.yMin !== undefined ? opts.yMin : 0;
    var y1 = opts.yMax !== undefined ? opts.yMax : Math.max.apply(null, ys) * 1.06;

    var sx = function (v) { return m.l + ((v - x0) / (x1 - x0)) * pw; };
    var sy = function (v) { return m.t + ph - ((v - y0) / (y1 - y0)) * ph; };

    var svg = el('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img',
      'aria-label': opts.alt || opts.yLabel });

    // grid + y ticks
    var yn = opts.yTicks || 5;
    for (var i = 0; i <= yn; i++) {
      var v = y0 + ((y1 - y0) * i) / yn, y = sy(v);
      svg.appendChild(el('line', { class: 'gr', x1: m.l, x2: m.l + pw, y1: y, y2: y }));
      svg.appendChild(el('text', { class: 'tick', x: m.l - 9, y: y + 3.5,
        'text-anchor': 'end' }, String(nice(v))));
    }
    // x ticks
    var xn = opts.xTicks || 6;
    for (var j = 0; j <= xn; j++) {
      var xv = x0 + ((x1 - x0) * j) / xn, x = sx(xv);
      svg.appendChild(el('line', { class: 'gr', x1: x, x2: x, y1: m.t, y2: m.t + ph }));
      svg.appendChild(el('text', { class: 'tick', x: x, y: m.t + ph + 17,
        'text-anchor': 'middle' }, String(nice(xv))));
    }

    // axes
    svg.appendChild(el('line', { class: 'ax', x1: m.l, x2: m.l, y1: m.t, y2: m.t + ph }));
    svg.appendChild(el('line', { class: 'ax', x1: m.l, x2: m.l + pw,
      y1: m.t + ph, y2: m.t + ph }));

    // axis labels
    svg.appendChild(el('text', { class: 'albl', x: m.l + pw / 2, y: H - 4,
      'text-anchor': 'middle' }, opts.xLabel));
    var yl = el('text', { class: 'albl', x: 12, y: m.t + ph / 2, 'text-anchor': 'middle',
      transform: 'rotate(-90 12 ' + (m.t + ph / 2) + ')' }, opts.yLabel);
    svg.appendChild(yl);

    // series
    opts.series.forEach(function (s) {
      var d = s.points.map(function (p, k) {
        return (k ? 'L' : 'M') + sx(p[0]).toFixed(2) + ' ' + sy(p[1]).toFixed(2);
      }).join(' ');
      if (s.fill) {
        svg.appendChild(el('path', {
          d: d + ' L' + sx(s.points[s.points.length - 1][0]) + ' ' + sy(y0) +
             ' L' + sx(s.points[0][0]) + ' ' + sy(y0) + ' Z',
          fill: s.fill, stroke: 'none' }));
      }
      svg.appendChild(el('path', { d: d, fill: 'none', stroke: s.colour,
        'stroke-width': s.width || 2, 'stroke-linejoin': 'round',
        'stroke-dasharray': s.dash || 'none' }));
      if (s.dots) {
        s.points.forEach(function (p) {
          svg.appendChild(el('circle', { cx: sx(p[0]), cy: sy(p[1]), r: 3,
            fill: s.colour }));
        });
      }
    });

    // marks
    (opts.marks || []).forEach(function (mk) {
      var x = sx(mk.x);
      svg.appendChild(el('line', { x1: x, x2: x, y1: m.t, y2: m.t + ph,
        stroke: mk.colour, 'stroke-width': 1, 'stroke-dasharray': '3 4' }));
      svg.appendChild(el('text', { class: 'tick', x: x + 5, y: m.t + 11,
        fill: mk.colour }, mk.label));
    });

    // legend
    if (opts.series.length > 1 || opts.legend) {
      var lx = m.l + 10, ly = m.t + 12;
      opts.series.forEach(function (s, k) {
        var yy = ly + k * 15;
        svg.appendChild(el('line', { x1: lx, x2: lx + 18, y1: yy, y2: yy,
          stroke: s.colour, 'stroke-width': 2, 'stroke-dasharray': s.dash || 'none' }));
        svg.appendChild(el('text', { class: 'tick', x: lx + 24, y: yy + 3.5 }, s.label));
      });
    }

    host.appendChild(svg);
  }

  /** Grouped bar chart for the per-ping energy split. */
  function bars(target, rows, opts) {
    var host = document.getElementById(target);
    if (!host) return;
    var W = 720, H = opts.height || 220;
    var m = { l: 58, r: 14, t: 16, b: 44 };
    var pw = W - m.l - m.r, ph = H - m.t - m.b;
    var max = Math.max.apply(null, rows.map(function (r) { return r.v; })) * 1.12;
    var svg = el('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img',
      'aria-label': opts.alt || '' });

    for (var i = 0; i <= 4; i++) {
      var v = (max * i) / 4, y = m.t + ph - (v / max) * ph;
      svg.appendChild(el('line', { class: 'gr', x1: m.l, x2: m.l + pw, y1: y, y2: y }));
      svg.appendChild(el('text', { class: 'tick', x: m.l - 9, y: y + 3.5,
        'text-anchor': 'end' }, String(nice(v))));
    }
    svg.appendChild(el('line', { class: 'ax', x1: m.l, x2: m.l + pw,
      y1: m.t + ph, y2: m.t + ph }));

    var bw = (pw / rows.length) * 0.56;
    rows.forEach(function (r, k) {
      var cx = m.l + (pw / rows.length) * (k + 0.5);
      var h = (r.v / max) * ph;
      svg.appendChild(el('rect', { x: cx - bw / 2, y: m.t + ph - h, width: bw,
        height: Math.max(h, 1), fill: r.colour, rx: 2 }));
      svg.appendChild(el('text', { class: 'tick', x: cx, y: m.t + ph - h - 6,
        'text-anchor': 'middle', fill: r.colour }, r.v.toFixed(2)));
      svg.appendChild(el('text', { class: 'tick', x: cx, y: m.t + ph + 16,
        'text-anchor': 'middle' }, r.k));
    });
    svg.appendChild(el('text', { class: 'albl', x: 12, y: m.t + ph / 2,
      'text-anchor': 'middle',
      transform: 'rotate(-90 12 ' + (m.t + ph / 2) + ')' }, opts.yLabel));
    host.appendChild(svg);
  }

  /* ---------------------------------------------------------------- */
  /* Figures                                                          */
  /* ---------------------------------------------------------------- */

  // 1. Absorption against frequency, sea water
  plot('fig-absorption', {
    xLabel: 'frequency  kHz', yLabel: 'absorption  dB/km',
    alt: 'Absorption rises steeply with frequency in sea water',
    series: [{ points: D.absorption.water, colour: '#2DD4C8',
      fill: 'rgba(45,212,200,.10)', label: 'Thorp, sea water' }],
    marks: [
      { x: 148, colour: '#F0A63C', label: '148 kHz  heavy sediment' },
      { x: 351, colour: '#6F8CA8', label: '351 kHz  clear water' }
    ],
    height: 260
  });

  // 2. Sound speed against temperature
  plot('fig-soundspeed', {
    xLabel: 'temperature  degC', yLabel: 'sound speed  m/s',
    yMin: 1400, yMax: 1560,
    alt: 'Sound speed against temperature at 35 ppt and 40 m',
    series: [{ points: D.soundSpeed, colour: '#2DD4C8', label: 'Mackenzie' }],
    height: 210
  });

  // 3. The adaptation sweep: centre frequency and resolution against turbidity
  plot('fig-sweep', {
    xLabel: 'turbidity  NTU', yLabel: 'centre frequency  kHz',
    yMin: 0, yMax: 400,
    alt: 'Chosen centre frequency falls as suspended sediment rises',
    series: [{ points: D.sweep.map(function (r) { return [r.ntu, r.fc]; }),
      colour: '#2DD4C8', label: 'chosen centre frequency', dots: true }],
    height: 240
  });

  plot('fig-sweep-res', {
    xLabel: 'turbidity  NTU', yLabel: 'value',
    alt: 'Range resolution coarsens and usable range recovers as frequency drops',
    yMin: 0, yMax: 400,
    series: [
      { points: D.sweep.map(function (r) { return [r.ntu, r.rangeM]; }),
        colour: '#F0A63C', label: 'usable range  m', dots: true },
      { points: D.sweep.map(function (r) { return [r.ntu, r.resMm * 30]; }),
        colour: '#6F8CA8', label: 'range resolution  mm x30', dots: true, dash: '5 4' }
    ],
    height: 240
  });

  // 4. Per-ping energy
  var p = D.power;
  bars('fig-power', [
    { k: 'wake', v: p.wake, colour: '#6F8CA8' },
    { k: 'sense', v: p.sample, colour: '#6F8CA8' },
    { k: 'synthesise', v: p.compute, colour: '#2DD4C8' },
    { k: 'transmit', v: p.transmit, colour: '#F0A63C' },
    { k: 'total', v: p.total, colour: '#EAF1F6' },
    { k: 'total, live sin()', v: p.naive, colour: '#E05A6B' }
  ], { yLabel: 'energy per ping  mJ', height: 230,
       alt: 'Energy split for one ping, table lookup against live trigonometry' });

  /* ---------------------------------------------------------------- */
  /* Tables filled from the same data                                 */
  /* ---------------------------------------------------------------- */

  var tb = document.getElementById('tb-sweep');
  if (tb) {
    D.sweep.forEach(function (r) {
      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td class="lb">' + r.ntu + '</td>' +
        '<td class="n hi">' + r.fc.toFixed(1) + '</td>' +
        '<td class="n">' + r.bw.toFixed(1) + '</td>' +
        '<td class="n">' + r.tauMs.toFixed(2) + '</td>' +
        '<td class="n">' + r.resMm.toFixed(1) + '</td>' +
        '<td class="n">' + r.rangeM + '</td>' +
        '<td class="n">' + r.snr.toFixed(1) + '</td>' +
        '<td class="n">' + r.gain.toFixed(1) + '</td>';
      tb.appendChild(tr);
    });
  }

  var tr2 = document.getElementById('tb-res');
  if (tr2) {
    D.resolution.rows.forEach(function (r) {
      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td class="lb">' + r.tauMs + '</td>' +
        '<td class="n">' + r.cwM.toFixed(3) + '</td>' +
        '<td class="n hi">' + r.chirpMm.toFixed(2) + '</td>' +
        '<td class="n">' + r.tbp + '</td>' +
        '<td class="n">' + r.gainDb.toFixed(1) + '</td>';
      tr2.appendChild(tr);
    });
  }

  var tw = document.getElementById('tb-window');
  if (tw) {
    var names = { rect: 'Rectangular', hann: 'Hann', hamming: 'Hamming',
      blackman: 'Blackman' };
    D.windows.forEach(function (w) {
      var tr = document.createElement('tr');
      tr.innerHTML = '<td class="lb">' + (names[w[0]] || w[0]) + '</td>' +
        '<td class="n hi">' + w[1].toFixed(1) + '</td>';
      tw.appendChild(tr);
    });
  }

  // Stamp the generation date wherever it is referenced.
  Array.prototype.forEach.call(document.querySelectorAll('.gen-date'), function (n) {
    n.textContent = D.generated;
  });
})();
